bounded_host_request.command:
set -eu
set -o pipefail
umask 077
p=/home/admin1/projects/debug-ai/.worktrees/independent-chat-20261128
sha=abb831082d0b858fad0563cce85babf7d5191a99
git -C "$p" fetch --no-tags origin "$sha"
test "$(git -C "$p" rev-parse FETCH_HEAD)" = "$sha"
tmp="$(mktemp -d)"
trap 'rm -rf -- "$tmp"' EXIT
git -C "$p" archive "$sha" server orchestrator | tar -x -C "$tmp"
cat > "$tmp/probe.cjs" <<'JS'
const fs=require("node:fs"),os=require("node:os"),path=require("node:path"),crypto=require("node:crypto"),http=require("node:http");
const {createAiCoreAdapter}=require("./server/adapters/ai-core.js");
const {createChatHandler}=require("./server/chat/index.js");
const {teachingTopics}=require("./server/command-module/teaching.js");
(async()=>{
 const gates=JSON.parse(process.env.DEBUG_AI_COMMAND_MODEL_GATES||"{}");
 if(!gates.qwen35)throw Error("QWEN_NOT_CONFIGURED");
 gates.deepseek={origin:"http://127.0.0.1:18186",model_id:"deepseek/deepseek-v4.1-flash-1017",max_output_tokens:1024,runtime_context_tokens:8192};
 const aiCore=createAiCoreAdapter({dispatchMode:"command_only",commandModelGates:gates,commandExternalQualification:true,timeoutMs:90000});
 const root=fs.mkdtempSync(path.join(os.tmpdir(),"real-teaching-")),token=crypto.randomBytes(24).toString("hex");
 const handler=createChatHandler({aiCore,runtimeRoot:root,token,teachingBudgets:{qwen35:Math.min(1024,gates.qwen35.max_output_tokens),deepseek:1024}});
 const server=http.createServer(async(req,res)=>{if(!await handler(req,res,new URL(req.url,"http://localhost")))res.writeHead(404).end();});
 try{
 await new Promise(r=>server.listen(0,"127.0.0.1",r));
 const url="http://127.0.0.1:"+server.address().port+"/chat/api",headers={Authorization:"Bearer "+token,"Content-Type":"application/json"};
 const topic="architecture",text=teachingTopics().find(x=>x.id===topic).label,turn_id=crypto.randomUUID();
 const res=await fetch(url,{method:"POST",headers,body:JSON.stringify({mode:"teaching",topic,text,turn_id}),signal:AbortSignal.timeout(225000)});
 const item=await res.json(),t=item.turns?.[0],s=t?.teaching?.stages||[];
 console.log(JSON.stringify({http:res.status,state:t?.state,error:t?.error,stages:s.map(x=>({phase:x.phase,model:x.model,model_id:x.model_id,state:x.state,error:x.error,cost:x.cost})),verdict:t?.teaching?.verdict,verification:t?.teaching?.verification,kb:t?.teaching?.kb_status,cost:t?.teaching?.cost_usd}));
 if(res.status!==200||t?.state!=="complete"||!s.some(x=>x.phase==="teacher_lesson"&&x.state==="complete")||!s.some(x=>x.phase==="student_attempt"&&x.state==="complete")||!s.some(x=>x.phase==="teacher_review_1"&&x.state==="complete"))process.exitCode=42;
 else {const read=await(await fetch(url+"/"+item.id,{headers})).json();if(read.turns?.[0]?.teaching?.stages?.length!==s.length)process.exitCode=43;}
 }finally{server.closeAllConnections();await new Promise(r=>server.close(r));fs.rmSync(root,{recursive:true,force:true});}
})().catch(e=>{console.error(e.code||e.name||"TEACHING_PROBE_ERROR");process.exitCode=44;});
JS
cid="$(docker ps -q --filter label=com.docker.compose.project=debug-ai --filter label=com.docker.compose.service=debug-ai)"
test -n "$cid"
tar -C "$tmp" -cf - server orchestrator probe.cjs | docker exec -i "$cid" sh -c 'set -eu; d=$(mktemp -d); trap "rm -rf -- \"$d\"" EXIT; tar -xf - -C "$d"; cd "$d"; NODE_PATH=/app/node_modules node probe.cjs'
